// QueryServer is the server API for Query service.
type QueryServer interface {
	// Secret queries a secret by ID, assembled with its guardian assignments
	// and revealed shares (the full pre-split wire shape).
	Secret(context.Context, *QuerySecretRequest) (*QuerySecretResponse, error)
	// Secrets queries all secrets (assembled views) with pagination.
	Secrets(context.Context, *QuerySecretsRequest) (*QuerySecretsResponse, error)
	// SecretsByCreator queries secrets by creator address (assembled views).
	SecretsByCreator(context.Context, *QuerySecretsByCreatorRequest) (*QuerySecretsByCreatorResponse, error)
	// PendingSecrets queries secrets in their active reveal phase
	// (pending/reconstructable), as assembled views.
	PendingSecrets(context.Context, *QueryPendingSecretsRequest) (*QueryPendingSecretsResponse, error)
	// SecretMeta queries only the slim secret metadata record — no share or
	// reveal data. The cheap call for light clients.
	SecretMeta(context.Context, *QuerySecretMetaRequest) (*QuerySecretMetaResponse, error)
	// SecretAssignments queries the per-guardian assignment status records for
	// a secret (tiny; no share bytes).
	SecretAssignments(context.Context, *QuerySecretAssignmentsRequest) (*QuerySecretAssignmentsResponse, error)
	// SecretReveals queries the revealed shares for a secret (what a recipient
	// needs to reconstruct).
	SecretReveals(context.Context, *QuerySecretRevealsRequest) (*QuerySecretRevealsResponse, error)
	// SecretShare queries a single guardian's encrypted share for a secret —
	// what a guardian daemon needs, without the other guardians' shares.
	SecretShare(context.Context, *QuerySecretShareRequest) (*QuerySecretShareResponse, error)
	// SecretPayload queries a secret's stored payload ciphertext (C) — what a
	// reconstruction client needs alongside the revealed key shares.
	SecretPayload(context.Context, *QuerySecretPayloadRequest) (*QuerySecretPayloadResponse, error)
	// HintsSince returns compact (secret_id, detection_hint) tuples for secrets
	// created at or after the given height, in creation order — the incremental
	// discovery-scan cursor. Recipients poll this, test each hint against their
	// private key client-side, and resume from their last scanned height.
	// A pruned secret's hint is deleted at Stage 2 (retention): discovery is
	// bounded by the retention window by design — scan at least every six months.
	HintsSince(context.Context, *QueryHintsSinceRequest) (*QueryHintsSinceResponse, error)
	// SecretTombstone returns the permanent tombstone of a pruned secret —
	// distinguishing "pruned" (archived, digest-verifiable) from "never
	// existed" (NotFound on both this and Query/Secret).
	SecretTombstone(context.Context, *QuerySecretTombstoneRequest) (*QuerySecretTombstoneResponse, error)
	// Guardian queries a guardian by address.
	Guardian(context.Context, *QueryGuardianRequest) (*QueryGuardianResponse, error)
	// Guardians queries all guardians with pagination.
	Guardians(context.Context, *QueryGuardiansRequest) (*QueryGuardiansResponse, error)
	// GuardianKeyHistory queries a guardian's append-only key-epoch history in
	// epoch order — what a daemon or client needs to resolve the epoch in
	// force at any height (newest entry with effective_from_height <= h).
	GuardianKeyHistory(context.Context, *QueryGuardianKeyHistoryRequest) (*QueryGuardianKeyHistoryResponse, error)
}

